// CHANGE-ME: Zammad-Gruppe + Requester ggf. anpassen (siehe docs/25-github-release-watcher.md fuer die Regeln dazu -- ZAMMAD_REQUESTER_EMAIL muss ein bereits existierender Zammad-User sein). Gruppe 'Support / Administration' angenommen als Unterguppe 'Administration' von 'Support' -> Zammad-API erwartet dafuer '::' als Trenner (siehe docs/25); falls es stattdessen eine einzelne Gruppe mit genau diesem Namen ist, hier auf 'Support / Administration' aendern.
const ZAMMAD_GROUP = 'Support::Administration';
const ZAMMAD_REQUESTER_EMAIL = 'info@edv-kretzer.de';
const GRAFANA_DASHBOARD_URL = 'https://grafana-tech.pke-lab.de/d/vereinsheim-alarmmonitor/vereinsheim-alarmmonitor';

const cpuRes = $('CPU abfragen').item.json;
const ramRes = $('RAM abfragen').item.json;
const tempRes = $('Temperatur abfragen').item.json;
const lastStartRes = $('Letzte AMweb-Anfrage abfragen').item.json;
const webhookBody = $('Alertmanager Webhook').item.json.body || {};

function firstValue(res) {
  const result = res && res.data && res.data.result;
  if (!result || result.length === 0) return null;
  return parseFloat(result[0].value[1]);
}

const cpu = firstValue(cpuRes);
const ram = firstValue(ramRes);
const temp = firstValue(tempRes);
const lastStartEpoch = firstValue(lastStartRes);
const lastStartText = (lastStartEpoch === null || Number.isNaN(lastStartEpoch))
  ? 'nie / unbekannt (alamos-apager hat noch keine /start-Anfrage fuer diese Station verzeichnet)'
  : new Date(lastStartEpoch * 1000).toISOString();

function fmt(v, unit) {
  return (v === null || Number.isNaN(v)) ? 'unbekannt' : `${v.toFixed(1)} ${unit}`;
}

const alert = (webhookBody.alerts && webhookBody.alerts[0]) || {};
const description = (alert.annotations && alert.annotations.description)
  || 'Vereinsheim-Alarmmonitor antwortet nicht mehr.';
const startsAt = alert.startsAt || new Date().toISOString();

const bodyText = [
  description,
  '',
  `Letzte erfolgreiche Anfrage der Alarmmonitor-Adresse (Kiosk hat zuletzt die echte AMweb-URL ueber alamos-apager angefragt): ${lastStartText}`,
  '',
  'Letzte bekannte Metriken vor dem Ausfall (nicht live -- der Pi ist ja gerade nicht erreichbar):',
  `- CPU: ${fmt(cpu, '%')}`,
  `- RAM: ${fmt(ram, '%')}`,
  `- Temperatur: ${fmt(temp, '°C')}`,
  '',
  `Alarm seit: ${startsAt}`,
  '',
  `Grafana-Dashboard (Vereinsheim-Alarmmonitor): ${GRAFANA_DASHBOARD_URL}`,
  '',
  'Das Problem wird so schnell es geht behoben, dies gilt lediglich als Information fuer dich.',
  '',
  '--',
  'Mit freundlichen Gruessen',
  'Peter Kretzer',
  '',
  'E-Mail: info@edv-kretzer.de',
  'Website: https://edv-kretzer.de/',
].join('\n');

return [{
  json: {
    title: 'Vereinsheim-Alarmmonitor nicht erreichbar',
    group: ZAMMAD_GROUP,
    customer: ZAMMAD_REQUESTER_EMAIL,
    article: {
      subject: 'Vereinsheim-Alarmmonitor nicht erreichbar',
      body: bodyText,
      content_type: 'text/plain',
      type: 'note',
      internal: false,
    },
  },
}];
